toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Sidebar */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2b2d31;
    color: #b5bac1;
    padding: 1rem 0;
    overflow-y: auto;
    border-right: 1px solid #1e1f22;
}

::deep .sidebar-title {
    padding: 0 1rem;
    margin: 0 0 0.5rem;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #949ba4;
}

::deep .channel-item {
    padding: 0.5rem 1rem;
    cursor: pointer;
    border-radius: 4px;
    margin: 0 0.5rem;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #35373c;
}

::deep .channel-item.active {
    background: #404249;
    color: #fff;
}

::deep .channel-name {
    font-weight: 500;
    font-size: 0.95rem;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #949ba4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    display: inline-block;
    background: #f23f43;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.1rem 0.4rem;
    border-radius: 8px;
    float: right;
    margin-top: -1.5rem;
}

/* Message Area */
.message-area {
    width: 55%;
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #dbdee1;
    transition: width 0.2s ease;
}

.message-area.expanded {
    width: 80%;
}

.message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

.message-area-header p {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
}

.loading-indicator {
    text-align: center;
    color: #949ba4;
    padding: 0.5rem;
    font-size: 0.85rem;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #949ba4;
}

/* Message Item */
::deep .message-item {
    position: relative;
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    margin-bottom: 0.25rem;
    transition: background 0.1s;
}

::deep .message-item:hover {
    background: #2e3035;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

::deep .message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #949ba4;
}

::deep .message-content {
    margin: 0.2rem 0 0.3rem;
    font-size: 0.9rem;
    line-height: 1.4;
}

::deep .message-reactions {
    display: flex;
    gap: 0.3rem;
    flex-wrap: wrap;
    margin-top: 0.3rem;
}

::deep .reaction-badge {
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.1rem 0.4rem;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.1s;
}

::deep .reaction-badge:hover {
    background: #3f4147;
}

::deep .thread-link {
    font-size: 0.8rem;
    color: #00a8fc;
    cursor: pointer;
    margin-top: 0.25rem;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.2rem;
}

::deep .action-btn {
    background: transparent;
    border: none;
    color: #b5bac1;
    cursor: pointer;
    font-size: 0.75rem;
    padding: 0.2rem 0.4rem;
    border-radius: 3px;
}

::deep .action-btn:hover {
    background: #3f4147;
    color: #fff;
}

::deep .emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 0.3rem;
    display: flex;
    gap: 0.2rem;
}

::deep .emoji-option {
    cursor: pointer;
    font-size: 1.2rem;
    padding: 0.2rem;
    border-radius: 4px;
}

::deep .emoji-option:hover {
    background: #3f4147;
}

/* Message Input */
::deep .message-input {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #3f4147;
    flex-shrink: 0;
}

::deep .message-input textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    color: #dbdee1;
    padding: 0.6rem 1rem;
    font-size: 0.9rem;
    resize: none;
    min-height: 2.5rem;
    max-height: 8rem;
    font-family: inherit;
}

::deep .message-input textarea:focus {
    outline: none;
    box-shadow: 0 0 0 1px #5865f2;
}

::deep .send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 0.5rem 1rem;
    font-weight: 600;
    cursor: pointer;
    align-self: flex-end;
    font-size: 0.85rem;
}

::deep .send-btn:hover:not(:disabled) {
    background: #4752c4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
    width: 25%;
    min-width: 250px;
    background: #2b2d31;
    color: #dbdee1;
    border-left: 1px solid #1e1f22;
    display: flex;
    flex-direction: column;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
}

::deep .thread-header h4 {
    margin: 0;
    color: #fff;
}

::deep .close-btn {
    background: transparent;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #3f4147;
    color: #fff;
}

::deep .thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
}

::deep .thread-reply {
    padding: 0.4rem 0;
    border-bottom: 1px solid #3f414722;
}

